const hits = new Map<string, { n: number; reset: number }>();

export function allow(ip: string): boolean {
  const now = Date.now();
  const h = hits.get(ip);
  if (!h || h.reset < now) {
    hits.set(ip, { n: 1, reset: now + 60_000 });
    return true;
  }
  h.n += 1;
  return h.n <= 100;
}

