import { S3Client, PutObjectCommand } from "@aws-sdk/client-s3";
import { getSignedUrl } from "@aws-sdk/s3-request-presigner";
import { randomUUID } from "node:crypto";

const s3 = new S3Client({
  region: "ap-northeast-2",
  // SDK 3.729+ adds a CRC32 checksum by default. In a presigned PUT that would be
  // the checksum of an empty body, so real uploads can fail. Only add it when required.
  requestChecksumCalculation: "WHEN_REQUIRED",
});
const ALLOWED = new Set(["image/jpeg", "image/png", "image/webp"]);

export async function createAvatarUpload(userId: string, contentType: string) {
  if (!ALLOWED.has(contentType)) throw new Error("unsupported type");

  // Never use the client's file name as the key
  const key = `avatars/${userId}/${randomUUID()}`;

  const url = await getSignedUrl(
    s3,
    new PutObjectCommand({ Bucket: process.env.BUCKET!, Key: key, ContentType: contentType }),
    {
      expiresIn: 300, // 5 minutes
      // v3 signs only "host" by default; without this the client can send any Content-Type
      signableHeaders: new Set(["content-type"]),
    }
  );

  // Browser: fetch(url, { method: "PUT", body: file, headers: { "Content-Type": contentType } })
  return { url, key };
}

