import { Pool } from "pg";
import type { APIGatewayProxyHandlerV2 } from "aws-lambda";

// Created once per execution environment, reused by warm invocations
const pool = new Pool({
  connectionString: process.env.DATABASE_URL, // points at a pooler, e.g. RDS Proxy
  max: 1,                         // one instance handles one request at a time
  idleTimeoutMillis: 10_000,
  connectionTimeoutMillis: 2_000,
});

export const handler: APIGatewayProxyHandlerV2 = async (event) => {
  const id = event.pathParameters?.id;
  if (!id) return { statusCode: 400, body: "missing id" };

  const { rows } = await pool.query("select id, name from products where id = $1", [id]);
  if (rows.length === 0) return { statusCode: 404, body: "not found" };

  return { statusCode: 200, body: JSON.stringify(rows[0]) };
};

