export default {
  async fetch(request: Request): Promise<Response> {
    const url = new URL(request.url);

    // Already localised: pass through to the origin / cache
    if (/^\/(ko|en|ru)(\/|$)/.test(url.pathname)) return fetch(request);

    // A user's explicit choice wins over geolocation
    const cookie = request.headers.get("Cookie") ?? "";
    const chosen = /(?:^|;\s*)lang=(ko|en|ru)/.exec(cookie)?.[1];

    const country = (request as Request & { cf?: { country?: string } }).cf?.country;
    const lang = chosen ?? (country === "KR" ? "ko" : "en");

    url.pathname = `/${lang}${url.pathname}`;
    return new Response(null, {
      status: 302,
      headers: { Location: url.toString(), "Cache-Control": "private, no-store" },
    });
  },
};

let currentUser: { id: string } | null = null;

export default {
  async fetch(request: Request, env: { API: string }): Promise<Response> {
    currentUser = await verifySession(request);
    if (!currentUser) return new Response("login", { status: 401 });

    const profile = await fetch(`${env.API}/profile`); // slow call
    const data = await profile.json();

    return Response.json({ user: currentUser.id, data });
  },
};

